import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Использование пакетов Laravel - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Конфигурационные файлы","slug":"конфигурационные-фаилы","link":"#конфигурационные-фаилы","children":[]},{"level":3,"title":"Псевдонимы и поставщики сервисов","slug":"псевдонимы-и-поставщики-сервисов","link":"#псевдонимы-и-поставщики-сервисов","children":[]},{"level":3,"title":"Миграции и модели","slug":"миграции-и-модели","link":"#миграции-и-модели","children":[]}],"relativePath":"3.x/ru/extend/resources/using-laravel-packages.md","filePath":"3.x/ru/extend/resources/using-laravel-packages.md"}'),r={name:"3.x/ru/extend/resources/using-laravel-packages.md"};function u(k,s,g,d,f,h){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Использование пакетов Laravel",-1)),a(t),s[1]||(s[1]=i(`<p>При включении пакетов Laravel в плагины October CMS есть несколько вещей, на которые следует обратить внимание.</p><h3 id="конфигурационные-фаилы"><a href="#конфигурационные-фаилы" class="header-anchor">#</a> Конфигурационные файлы</h3><p>Пакеты Laravel часто предоставляют конфигурационные файлы. Вы должны продублировать эту конфигурацию в директорию вашего плагина. Например, если файл назывался <strong>purifier.php</strong> и содержал некоторые базовые значения конфигурации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;encoding&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;UTF-8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;finalize&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cachePath&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">storage_path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app/purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cacheFileMode&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0755</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Скопируйте этот файл в директорию вашего плагина, например, <strong>plugins/acme/blog/config/purifier.php</strong>. Важно скопировать и поддерживать весь файл, так как отсутствующие ключи не будут унаследованы из базовой конфигурации.</p><p>Далее вы должны перенести содержимое конфигурации вашего плагина в конфигурацию пакета внутри метода <code>boot()</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Это установит все значения конфигурации пакета равными значениям конфигурации вашего плагина. Следующие значения будут равны.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier.encoding&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier.encoding&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Теперь вы можете предоставлять значения конфигурации пакета так же, как и обычные значения конфигурации плагина, используя <a href="./../settings/file-settings.html">стандартный подход к конфигурации</a>.</p><h3 id="псевдонимы-и-поставщики-сервисов"><a href="#псевдонимы-и-поставщики-сервисов" class="header-anchor">#</a> Псевдонимы и поставщики сервисов</h3><p>Если пакет Laravel содержит поставщиков сервисов и псевдонимы, вы должны вручную зарегистрировать их в ваших плагинах, используя фасад <code>App</code> в методе <code>register()</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Register the aliases provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">registerClassAlias</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>Facades<span class="token punctuation">\\</span>Purifier</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Register the service providers provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>PurifierServiceProvider</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="миграции-и-модели"><a href="#миграции-и-модели" class="header-anchor">#</a> Миграции и модели</h3><p>Пакеты Laravel, которые взаимодействуют с базой данных, часто включают собственные миграции базы данных и модели Eloquent. Вы должны продублировать эти миграции и модели в директорию вашего плагина.</p><p>Убедитесь, что классы моделей наследуют базовый класс <code>October\\Rain\\Database\\Model</code> вместо базового класса модели Laravel Eloquent, чтобы воспользоваться расширенными технологическими возможностями October CMS.</p><p>Также хорошей идеей будет переименовать таблицы базы данных и добавить к ним префикс с кодом вашего автора и именем плагина. Например, таблица с именем <code>posts</code> должна быть переименована в <code>rainlab_blog_posts</code>.</p>`,17))])}const _=p(r,[["render",u]]);export{v as __pageData,_ as default};
